//! The C side: csrc/pentools.c (which end of the pen is near, from the
//! Wayland tablet protocol: SDL does not tell) and the protocol's glue,
//! generated by wayland-scanner from wayland-protocols' tablet-v2.xml.
use std::env;
use std::path::PathBuf;
use std::process::Command;

fn main() {
    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
    let xml = env::var("TABLET_V2_XML")
        .unwrap_or_else(|_| "/usr/share/wayland-protocols/stable/tablet/tablet-v2.xml".to_owned());
    for (mode, file) in [
        ("client-header", "tablet-v2-client-protocol.h"),
        ("private-code", "tablet-v2-protocol.c"),
    ] {
        let ok = Command::new("wayland-scanner")
            .args([mode, &xml, out.join(file).to_str().unwrap()])
            .status()
            .expect("wayland-scanner (libwayland-bin)")
            .success();
        assert!(ok, "wayland-scanner {mode} {xml}");
    }
    cc::Build::new()
        .file("csrc/pentools.c")
        .file(out.join("tablet-v2-protocol.c"))
        .include(&out)
        .flag_if_supported("-Wno-unused-parameter")
        .flag_if_supported("-Wno-strict-prototypes")
        .compile("pentools");
    println!("cargo:rustc-link-lib=wayland-client");
    println!("cargo:rerun-if-changed=csrc/pentools.c");
    println!("cargo:rerun-if-env-changed=TABLET_V2_XML");
}
